    const input = h('input', { type: 'text', maxlength: '300', placeholder: '덧붙일 말 (선택)', 'aria-label': '덧붙일 말 (선택)' }) as HTMLInputElement;
    const msg = h('p', { class: 'form-msg', role: 'status' });
